"""policy.ini (docs/policy.md)."""

import re
from dataclasses import dataclass, replace
from datetime import timedelta, timezone
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError


@dataclass(frozen=True)
class Settings:
    max_size: int | None = None
    max_age: timedelta | None = None
    naming: str = "numbered"
    offset: timezone = timezone.utc
    compress_after: int = 1
    keep: int = 5
    keep_days: int | None = None


_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)", re.ASCII)
_DURATION = re.compile(r"([0-9]+)([mhd])", re.ASCII)
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})", re.ASCII)
_INT = re.compile(r"[0-9]+", re.ASCII)
_SECTION = re.compile(r"\[(.*)\]", re.DOTALL)
_UNITS = {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}


def _bad(msg):
    return DataError("policy", f"policy.ini: {msg}")


def _size(v):
    m = _SIZE.fullmatch(v)
    if v == "off":
        return None
    if not m:
        raise _bad(f"bad size {v!r}")
    return int(m.group(1)) * _UNITS[m.group(2).lower()]


def _age(v):
    if v == "off":
        return None
    m = _DURATION.fullmatch(v)
    if not m:
        raise _bad(f"bad duration {v!r}")
    n = int(m.group(1))
    return {"m": timedelta(minutes=n), "h": timedelta(hours=n), "d": timedelta(days=n)}[m.group(2)]


def _naming(v):
    if v not in ("numbered", "dated"):
        raise _bad(f"bad naming {v!r}")
    return v


def _offset(v):
    m = _OFFSET.fullmatch(v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise _bad(f"bad offset {v!r}")
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return timezone(-delta if m.group(1) == "-" else delta)


def _count(minimum, allow_off=False):
    def parse(v):
        if allow_off and v == "off":
            return None
        if not _INT.fullmatch(v) or int(v) < minimum:
            raise _bad(f"bad number {v!r}")
        return int(v)

    return parse


_KEYS = {
    "max_size": _size,
    "max_age": _age,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _count(0),
    "keep": _count(1),
    "keep_days": _count(1, allow_off=True),
}


class Policy:
    def __init__(self, defaults: dict, sections: dict):
        self._defaults = defaults
        self._sections = sections

    def stream_names(self) -> set:
        return set(self._sections)

    def settings(self, name: str) -> Settings:
        values = dict(self._defaults)
        values.update(self._sections.get(name, {}))
        return replace(Settings(), **values)


def load(path: Path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    defaults: dict | None = None
    sections: dict = {}
    current: dict | None = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        m = _SECTION.fullmatch(line)
        if m:
            title = m.group(1)
            if title == "defaults":
                if defaults is not None:
                    raise _bad("section [defaults] twice")
                defaults = current = {}
            elif title.startswith("stream ") and streams.valid(title[7:]):
                name = title[7:]
                if name in sections:
                    raise _bad(f"section {name} twice")
                sections[name] = current = {}
            else:
                raise _bad(f"unknown section {title!r}")
            continue
        if current is None or "=" not in line:
            raise _bad(f"bad line {line!r}")
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if key not in _KEYS:
            raise _bad(f"unknown key {key!r}")
        if key in current:
            raise _bad(f"key {key} twice")
        current[key] = _KEYS[key](value)
    return Policy(defaults or {}, sections)

