    re.ASCII,
)


def parse_time(text: str, legacy: bool = True) -> datetime | None:
    """A time of data.md, section 2, as an aware datetime; None when text is not one.

    The form `YYYY-MM-DD HH:MM:SS` (release 1.2, UTC) is read only with `legacy`.
    """
    m = _TIME.fullmatch(text)
    if not m:
        return None
    try:
        y, mo, d = int(m[1]), int(m[2]), int(m[3])
        if m[8] is not None:
            h, mi, s = int(m[4]), int(m[5]), int(m[6])
            micro = int(m[7][:6].ljust(6, "0")) if m[7] else 0
            if m[8] == "Z":
                tz = timezone.utc
            else:
                oh, om = int(m[8][1:3]), int(m[8][4:6])
                if oh > 23 or om > 59:
                    return None
                delta = timedelta(hours=oh, minutes=om)
                tz = timezone(-delta if m[8][0] == "-" else delta)
            return datetime(y, mo, d, h, mi, s, micro, tzinfo=tz)
        if not legacy:
            return None
        return datetime(y, mo, d, int(m[9]), int(m[10]), int(m[11]), tzinfo=timezone.utc)
    except ValueError:
        return None


