"""rotate (docs/rotate.md)."""

import gzip
import re
from dataclasses import dataclass
from datetime import timedelta

from logkeep import dates, policy as policy_mod, state as state_mod, streams
from logkeep.errors import DataError, Refused


@dataclass
class Archive:
    old: str | None  # file name before the run; None for the new archive
    key: tuple  # age order key, bigger is newer
    compressed: bool
    plain_name: str  # name without .gz (new archive: the name it is created with)
    new: bool = False
    final: str = ""
    compress_now: bool = False
    removed: bool = False


def _state_error(msg):
    return DataError("state", f"state.json: {msg}")


def _check_state(entries: dict, existing: set) -> None:
    for name in sorted(existing):
        entry = entries.get(name)
        if entry is None:
            continue
        if "opened" in entry and (
            not isinstance(entry["opened"], str) or dates.parse_time(entry["opened"]) is None
        ):
            raise _state_error(f"{name}: bad opened")
        if "rotations" in entry:
            r = entry["rotations"]
            if isinstance(r, bool) or not isinstance(r, int) or r < 0:
                raise _state_error(f"{name}: bad rotations")
        if "archives" in entry:
            arch = entry["archives"]
            if not isinstance(arch, dict):
                raise _state_error(f"{name}: archives is not an object")
            for k, v in arch.items():
                if not isinstance(v, str) or dates.parse_time(v) is None:
                    raise _state_error(f"{name}: bad time for {k}")


def _list_archives(ctx, name: str, naming: str) -> list[Archive]:
    d = streams.logs_dir(ctx.data)
    if naming == "numbered":
        pat = re.compile(re.escape(name) + r"\.log\.([1-9][0-9]*)(\.gz)?", re.ASCII)
    else:
        pat = re.compile(
            re.escape(name) + r"\.log\.([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?", re.ASCII
        )
    found = []
    if d.is_dir():
        for p in d.iterdir():
            m = pat.fullmatch(p.name)
            if not m or not p.is_file():
                continue
            if naming == "numbered":
                key = (-int(m[1]),)
                compressed = m[2] is not None
                plain = p.name[:-3] if compressed else p.name
            else:
                try:
                    day = dates.datetime.strptime(m[1], "%Y-%m-%d").date()
                except ValueError:
                    continue
                key = (day.toordinal(), int(m[2]) if m[2] else 1)
                compressed = m[3] is not None
                plain = p.name[:-3] if compressed else p.name
            found.append(Archive(p.name, key, compressed, plain))
    places = set()
    for a in found:
        if a.key in places:
            raise DataError("archives", f"{name}: two archives in the same place")
        places.add(a.key)
    found.sort(key=lambda a: a.key, reverse=True)
    return found


def _active_age_start(path, entry):
    if entry is not None and "opened" in entry:
        return dates.parse_time(entry["opened"])
    with path.open("rb") as f:
        first = f.readline()
    first = first.rstrip(b"\r\n")
    token = first.split(b" ", 1)[0]
    try:
        text = token.decode("ascii")
    except UnicodeDecodeError:
        return None
    return dates.parse_time(text, legacy=False)


def _decide(ctx, name, st, entry, force) -> str | None:
    path = streams.log_path(ctx.data, name)
    if not path.is_file():
        return "no log"
    size = path.stat().st_size
    if size == 0:
        return "empty"
    if force:
        return "forced"
    if st.max_size is not None and size >= st.max_size:
        return "size"
    if st.max_age is not None:
        start = _active_age_start(path, entry)
        if start is not None and ctx.now - start >= st.max_age:
            return "age"
    return "not due"


def run(ctx, names: list[str], dry_run: bool, force: bool) -> list[str]:
    pol = policy_mod.load(ctx.policy_path)
    doc = ctx.state
    entries = doc["streams"]
    existing = set(streams.active(ctx.data)) | pol.stream_names()
    _check_state(entries, existing)
    if names:
        todo = sorted(set(names))
        for n in todo:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
    else:
        todo = sorted(existing)

    plans = []
    for name in todo:
        st = pol.settings(name)
        archives = _list_archives(ctx, name, st.naming)
        plans.append((name, st, archives))

    out = []
    n_rot = n_rem = n_comp = 0
    new_entries = {}
    actions = []  # (name, plan pieces) executed after all checks
    for name, st, archives in plans:
        entry = entries.get(name)
        what = _decide(ctx, name, st, entry, force)
        rotated = what in ("forced", "size", "age")
        times = dict((entry or {}).get("archives", {}))
        if rotated:
            if st.naming == "numbered":
                new = Archive(None, (1,), False, f"{name}.log.1", new=True)
            else:
                day = ctx.now.astimezone(st.offset).date()
                same = [a.key[1] for a in archives if a.key[0] == day.toordinal()]
                plain = f"{name}.log.{day.isoformat()}"
                k = max(same) + 1 if same else 1
                if k > 1:
                    plain += f".{k}"
                new = Archive(None, (day.toordinal(), k), False, plain, new=True)
            archives = sorted(archives + [new], key=lambda a: a.key, reverse=True)
        for pos, a in enumerate(archives, 1):
            if pos > st.keep:
                a.removed = True
            elif not a.new and st.keep_days is not None and a.old in times:
                t = dates.parse_time(times[a.old])
                if ctx.now - t >= timedelta(days=st.keep_days):
                    a.removed = True
        kept = [a for a in archives if not a.removed]
        for i, a in enumerate(kept):
            a.compress_now = i >= st.compress_after and not a.compressed
            gz = a.compressed or a.compress_now
            if st.naming == "numbered":
                a.final = f"{name}.log.{i + 1}" + (".gz" if gz else "")
            else:
                a.final = a.plain_name + (".gz" if gz else "")
        out.append(f"{name}: " + (f"rotate ({what})" if rotated else what))
        for a in kept:
            if a.new:
                out.append(f"  new {a.final}")
            elif a.final != a.old:
                out.append(f"  {a.final} <- {a.old}")
            else:
                out.append(f"  {a.final}")
        for a in archives:
            if a.removed:
                out.append(f"  remove {a.old if a.old else a.plain_name}")
        n_rot += rotated
        n_rem += sum(a.removed for a in archives)
        n_comp += sum(a.compress_now for a in kept)

        new_entry = {}
        if rotated:
            new_entry["opened"] = ctx.stamp
        elif entry is not None and "opened" in entry:
            new_entry["opened"] = entry["opened"]
        new_entry["rotations"] = ((entry or {}).get("rotations", 0)) + (1 if rotated else 0)
        arch_times = {}
        for a in kept:
            if a.new:
                arch_times[a.final] = ctx.stamp
            elif a.old in times:
                arch_times[a.final] = times[a.old]
        new_entry["archives"] = arch_times
        new_entries[name] = new_entry
        actions.append((name, rotated, archives))

    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    # Everything is checked; now write.
    logs = streams.logs_dir(ctx.data)
    contents = {}
    for name, rotated, archives in actions:
        for a in archives:
            if a.removed:
                continue
            if a.new:
                contents[id(a)] = streams.log_path(ctx.data, name).read_bytes()
            elif a.final != a.old:
                contents[id(a)] = (logs / a.old).read_bytes()
    for name, rotated, archives in actions:
        for a in archives:
            if a.old is not None and (a.removed or a.final != a.old):
                (logs / a.old).unlink()
    for name, rotated, archives in actions:
        for a in archives:
            if a.removed or id(a) not in contents:
                continue
            data = contents[id(a)]
            if a.compress_now:
                data = gzip.compress(data, mtime=0)
            (logs / a.final).write_bytes(data)
        if rotated:
            streams.log_path(ctx.data, name).write_bytes(b"")
    entries.update(new_entries)
    ctx.data.mkdir(parents=True, exist_ok=True)
    state_mod.save(ctx.state_path, doc)
    return out

